package io.github.samlinb.openbone.io;

import java.nio.file.*;
import java.util.*;
import io.github.samlinb.openbone.application.*;
import io.github.samlinb.openbone.core.animation.*;
import io.github.samlinb.openbone.core.math.*;
import io.github.samlinb.openbone.core.model.*;
import org.junit.jupiter.api.*;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.ValueSource;
import static io.github.samlinb.openbone.TestData.id;
import static org.junit.jupiter.api.Assertions.*;

class ConstraintTimelineCodecTest {
 static final EntityId CLIP=AnimationClip.DEFAULT_ID;
 static DocumentSnapshot base(){return new DocumentSnapshot(List.of(new Bone(id(1),"root",null,Transform.IDENTITY,0),new Bone(id(2),"arm",id(1),new Transform(10,0,0,1,1),100),new Bone(id(3),"target",id(1),new Transform(80,60,0,1,1),0)),List.of(),List.of());}
 static DocumentSnapshot ik(){return base().withConstraints(List.of(new IkConstraint(id(5),"key/name~IK",0,true,List.of(id(2)),id(3),.25,0,true,false,false,false)));}
 static DocumentSnapshot stepped(DocumentSnapshot d,ConstraintChannel channel,List<Double> first,List<Double> second){d=AnimationEdits.putConstraint(d,CLIP,id(5),channel,.25,first);d=AnimationEdits.putConstraint(d,CLIP,id(5),channel,1,second);var key=d.animation(CLIP).constraintTracks().stream().filter(t->t.channel()==channel).findFirst().orElseThrow().keys().get(0);return AnimationEdits.curves(d,CLIP,Set.of(key.id()),List.of(Curve.STEPPED));}
 static void compare(DocumentSnapshot a,DocumentSnapshot b){for(double time:new double[]{0,.249,.25,.6,.999,1,2}){var left=AnimationSampler.constraints(a,a.animations().get(0).id(),time,false).get(0);var right=AnimationSampler.constraints(b,b.animations().get(0).id(),time,false).get(0);for(var channel:ConstraintChannel.values())if(channel.supports(left))assertEquals(channel.values(left),channel.values(right),channel+"@"+time);var x=AnimationSampler.world(a,a.animations().get(0).id(),time,false).bones().get(id(2)).matrix();var arm=b.bones().stream().filter(v->v.name().equals("arm")).findFirst().orElseThrow();var y=AnimationSampler.world(b,b.animations().get(0).id(),time,false).bones().get(arm.id()).matrix();assertEquals(x,y);}}
 @Test void steppedIkAllFieldsAbsoluteAndNamedRoundtrip()throws Exception{var d=stepped(ik(),ConstraintChannel.IK,List.of(.2,0.,1.,1.,0.),List.of(.8,0.,0.,0.,1.));var codec=new SkeletonJsonCodec();var bytes=codec.encode(d,Map.of(),"");var root=new com.fasterxml.jackson.databind.ObjectMapper().readTree(bytes);assertTrue(root.path("animations").path(d.animations().get(0).name()).path("ik").has("key/name~IK"));assertTrue(root.path("animations").path(d.animations().get(0).name()).path("ik").path("key/name~IK").get(0).path("compress").isBoolean());compare(d,codec.decode(bytes,Path.of("D:/tmp")));}
 @ParameterizedTest @ValueSource(ints={0,1,2,3}) void steppedTransformAllModesSixMixRoundtrip(int mode)throws Exception{var d=base().withConstraints(List.of(new TransformConstraint(id(5),"transform",0,true,List.of(id(2)),id(3),(mode&1)!=0,(mode&2)!=0,Collections.nCopies(6,0.),Collections.nCopies(6,0.))));d=stepped(d,ConstraintChannel.TRANSFORM_MIX,Collections.nCopies(6,.25),Collections.nCopies(6,.75));var codec=new SkeletonJsonCodec();compare(d,codec.decode(codec.encode(d,Map.of(),""),Path.of("D:/tmp")));}
 @Test void steppedPathIndependentGroupsAndNoncoincidentBoundariesRoundtrip()throws Exception{var path=new PathAttachment(id(7),"path",id(6),List.of(new Vec2(-30,0),new Vec2(0,0),new Vec2(40,0),new Vec2(80,0),new Vec2(120,0),new Vec2(150,0)),false,true,List.of(120.,0.));var d=new DocumentSnapshot(base().bones(),List.of(new Slot(id(6),"path-slot",id(1),id(7))),List.of(path)).withConstraints(List.of(new PathConstraint(id(5),"path",0,true,List.of(id(2)),id(6),PathConstraint.PositionMode.FIXED,PathConstraint.SpacingMode.FIXED,PathConstraint.RotateMode.TANGENT,0,20,0,1,1,1)));d=stepped(d,ConstraintChannel.PATH_POSITION,List.of(30.),List.of(90.));d=stepped(d,ConstraintChannel.PATH_SPACING,List.of(20.),List.of(40.));d=stepped(d,ConstraintChannel.PATH_MIX,List.of(.25,.5,.75),List.of(.75,.5,.25));var key=d.animation(CLIP).constraintTracks().get(1).keys().get(0).id();d=AnimationEdits.move(d,CLIP,Set.of(key),.125);var codec=new SkeletonJsonCodec();compare(d,codec.decode(codec.encode(d,Map.of(),""),Path.of("D:/tmp")));}
 @Test void groupDefaultsAndUnknownNameTypeAndFieldsArePrecise()throws Exception{var mapper=new com.fasterxml.jackson.databind.ObjectMapper();var codec=new SkeletonJsonCodec();var root=mapper.readTree(codec.encode(ik(),Map.of(),""));var animation=(com.fasterxml.jackson.databind.node.ObjectNode)root.path("animations").path(ik().animations().get(0).name());animation.putObject("ik").putArray("key/name~IK").addObject().put("time",1);var imported=codec.decode(mapper.writeValueAsBytes(root),Path.of("D:/tmp"));assertEquals(List.of(1.,0.,1.,0.,0.),imported.animations().get(0).constraintTracks().get(0).keys().get(0).values());for(String mutation:List.of("unknownName","wrongSection","unknownField","booleanNumber","reset","badCurveSize")){var copy=root.deepCopy();var a=(com.fasterxml.jackson.databind.node.ObjectNode)copy.path("animations").path(ik().animations().get(0).name());var keys=a.path("ik").path("key/name~IK");switch(mutation){case "unknownName"->{var n=(com.fasterxml.jackson.databind.node.ObjectNode)a.path("ik");n.set("unknown",n.remove("key/name~IK"));}case "wrongSection"->a.set("transform",a.remove("ik"));case "unknownField"->((com.fasterxml.jackson.databind.node.ObjectNode)keys.get(0)).put("uniform",true);case "booleanNumber"->((com.fasterxml.jackson.databind.node.ObjectNode)keys.get(0)).put("bendPositive",1);case "reset"->a.putObject("physics").putArray("reset");case "badCurveSize"->((com.fasterxml.jackson.databind.node.ObjectNode)keys.get(0)).putArray("curve").add(1);}assertThrows(ProjectFormatException.class,()->codec.decode(mapper.writeValueAsBytes(copy),Path.of("D:/tmp")),mutation);}}
 @Test void continuousAndAnimatedBoneDomainsRefusedWithoutLosingOwnData()throws Exception{var d=stepped(ik(),ConstraintChannel.IK,List.of(.2,0.,1.,0.,0.),List.of(.8,0.,1.,0.,0.));var key=d.animation(CLIP).constraintTracks().get(0).keys().get(0).id();var continuous=AnimationEdits.curves(d,CLIP,Set.of(key),List.of(Curve.LINEAR));var own=new ProjectCodec();assertEquals(continuous,own.decode(own.encode(continuous)));assertTrue(assertThrows(ProjectFormatException.class,()->RuntimeRange.validate(continuous)).getMessage().contains(".curve"));var animated=AnimationEdits.put(d,CLIP,id(3),Channel.TRANSLATE,1,List.of(1.,2.));assertTrue(assertThrows(ProjectFormatException.class,()->RuntimeRange.validate(animated)).getMessage().contains(".bones"));}
 @Test void mixedGroupCurvesCannotBeSilentlyCollapsedOnWrite()throws Exception{var d=base().withConstraints(List.of(new TransformConstraint(id(5),"transform",0,true,List.of(id(2)),id(3),false,false,Collections.nCopies(6,0.),Collections.nCopies(6,0.))));d=stepped(d,ConstraintChannel.TRANSFORM_MIX,Collections.nCopies(6,0.),Collections.nCopies(6,1.));var id=d.animation(CLIP).keys().get(0).id();d=AnimationEdits.curves(d,CLIP,Set.of(id),List.of(Curve.STEPPED,Curve.LINEAR,Curve.LINEAR,Curve.LINEAR,Curve.LINEAR,Curve.LINEAR));var candidate=d;assertTrue(assertThrows(ProjectFormatException.class,()->ConstraintTimelineJson.write(new com.fasterxml.jackson.databind.ObjectMapper().createObjectNode(),candidate,candidate.animation(CLIP))).getMessage().contains("combine stepped"));}
 @Test void exhaustiveCertificateBudgetAndCrossGroupFloatBoundariesAreGuarded()throws Exception{
  var keys=new ArrayList<Keyframe>();for(int n=0;n<513;n++)keys.add(new Keyframe(EntityId.create(),n,List.of(.5,0.,1.,0.,0.),Collections.nCopies(5,Curve.STEPPED)));var large=ik().withAnimations(List.of(new AnimationClip(CLIP,"many",List.of(),List.of(),List.of(new ConstraintTimeline(id(5),ConstraintChannel.IK,keys)))));var own=new ProjectCodec();assertEquals(large,own.decode(own.encode(large)));assertTrue(assertThrows(ProjectFormatException.class,()->RuntimeRange.validate(large)).getMessage().contains("budget"));
  var d=ik();var bones=new ArrayList<>(d.bones());bones.add(new Bone(id(8),"other arm",id(1),new Transform(0,-20,0,1,1),80));d=new DocumentSnapshot(bones,d.slots(),d.attachments(),d.animations(),List.of(d.constraint(id(5)),new IkConstraint(id(9),"other",1,true,List.of(id(8)),id(3),1,0,true,false,false,false)));d=AnimationEdits.putConstraint(d,CLIP,id(5),ConstraintChannel.IK,1,List.of(.5,0.,1.,0.,0.));d=AnimationEdits.putConstraint(d,CLIP,id(9),ConstraintChannel.IK,1+Math.scalb(1.,-30),List.of(.5,0.,1.,0.,0.));var collapsed=d;assertEquals(d,own.decode(own.encode(d)));assertTrue(assertThrows(ProjectFormatException.class,()->RuntimeRange.validate(collapsed)).getMessage().contains("across parameter groups"));
 }
}
